// tokenshave — generated by `npx tokenshave install` (Codex CLI hook) on repo build — regenerate with `npm run gen:codex-mod` (tokenshave 0.6.0)
// Uninstall with `npx tokenshave uninstall`, or delete this file/directory.
//
// Codex CLI PostToolUse hook for the Bash tool: replaces the model-visible
// result of a completed shell command with its shaved form. The engine is
// inlined below (pure computation: no imports, no network, no data
// collection) and you can read every line it runs.
//
// Contract, per codex-rs 0.166.0 (openai/codex sources, see VERIFY.md):
//  - stdin: one JSON object { tool_name: "Bash", tool_input: { command },
//    tool_response: <model-facing output string>, ... }
//  - stdout JSON { continue: false, reason: <text>, stopReason: <short> }
//    replaces the tool result the model sees; empty stdout + exit 0 keeps
//    the original result untouched (fail open — every path below prints
//    nothing on any error or pass-through case, and this file always
//    exits 0, which the command runner runs through the platform shell)

// --- engine/tokens.js ---
/** Rough token estimate. Code/text averages ~4 characters per token. */
function estimateTokens(text) {
    return Math.ceil(text.length / 4);
}

// --- engine/diff.js ---
/**
 * Shaving for unified diffs (git diff): context lines are the least
 * valuable and the most repetitive. Keep everything that expresses a
 * change; drop pure context.
 *
 * Also collapses non-diff noise (git stderr like CRLF warnings) that got
 * mixed into the tool result — it is hard to read without diff structure
 * and often repeats dozens of times.
 */
/** A diff line: adds, deletions, hunk headers, headers, "\ No newline" notes. */
const DIFF_SYNTAX = /^(\+|-|@@|\\|diff --git|index |--- |\+\+\+ )/;
const MARKER = "␥ ... (tokenshave: %d of %d diff lines removed)";
function shaveDiff(output) {
    const lines = output.split("\n");
    const total = lines.length;
    const kept = [];
    const noise = [];
    let contextRemoved = 0;
    for (const line of lines) {
        // unified diff context line starts with a single space
        const isContext = line.startsWith(" ") && !line.startsWith(" +++") && !line.startsWith(" ---");
        if (isContext) {
            contextRemoved++;
            continue;
        }
        if (!DIFF_SYNTAX.test(line)) {
            // stderr noise mixed into the tool result
            noise.push(line);
            continue;
        }
        kept.push(line);
    }
    // keep the first two noise lines in case a lone error lives there
    const noiseKept = noise.slice(0, 2);
    const removed = contextRemoved + (noise.length - noiseKept.length);
    if (removed === 0)
        return { output, removed: 0 };
    const out = [
        MARKER.replace("%d", String(removed)).replace("%d", String(total)),
    ];
    out.push(...noiseKept);
    out.push(...kept);
    return { output: out.join("\n"), removed };
}

// --- engine/rules.js ---
/**
 * Per-tool shaving rules.
 *
 * A rule decides how aggressively we trim the output of a given command:
 *  - head:   always keep the first N lines (banner, first file listed...)
 *  - tail:   always keep the last N lines (summaries live at the bottom)
 *  - keep:   always keep any line matching this (errors, failures)
 *  - budget: if the whole output fits in this many lines, leave it untouched
 */
/** Lines that always matter regardless of tool. No leading \b on "error":
 * "AssertionError" etc. must match too (letter before "Error" kills \b).
 * TAP "not ok" carries failing test names that no other line repeats, and
 * live QA caught shaving them (VERIFY.md). */
const ALWAYS_KEEP = /(failed|fails|failure|fatal|error|not ok|warn(?:ing)?|exception|panic|denied|exit(?:ed)? with|exit code|ENOENT|ENOTFOUND|ERESOLVE|EACCES|ERR!|✗|✖|●)/i;
/**
 * Tool families. Order matters: first match wins, so put the
 * most specific rules at the top.
 */
const RULES = [
    {
        name: "package-manager-install",
        // npm install / pnpm add / yarn add / pip install / cargo add / go get / docker pull
        match: /(^|[\s(])(npm|pnpm|yarn|bun)\s+\w*i(nstall|all)?\b|(^|[\s(])(npm|pnpm|yarn|bun)\s+add\b|pip3?\s+install|cargo\s+add|go\s+get\b|docker\s+pull\b|apt(-get)?\s+install|brew\s+install/,
        head: 3,
        tail: 8,
        keep: ALWAYS_KEEP,
        budget: 20,
    },
    {
        name: "test-runner",
        // vitest / jest / pytest / rspec / go test / cargo test / npx playwright
        match: /\b(vitest|jest|pytest|rspec|playwright|mocha|karma)\b|^go\s+test\b|\bcargo\s+test\b|(^|[\s(])node\s+--test\b/,
        head: 4,
        tail: 12,
        keep: ALWAYS_KEEP,
        budget: 40,
    },
    {
        name: "compiler",
        // tsc / gcc / clang / go vet / cargo build
        match: /\btsc\b|(^|[\s(])gcc|(^|[\s(])clang|go\s+vet\b|cargo\s+build\b|gradle\s+\w*build|mvn\s+\w*package/,
        head: 4,
        tail: 10,
        keep: ALWAYS_KEEP,
        budget: 40,
    },
    {
        name: "bundler-build",
        // vite build / webpack / next build / esbuild / rollup
        match: /\b(vite|webpack|esbuild|rollup)\s+build|next\s+build\b|turbopack\b/,
        head: 4,
        tail: 12,
        keep: ALWAYS_KEEP,
        budget: 40,
    },
    {
        name: "http-client",
        // curl/wget/postman style — headers and 200-line HTML bodies are noise
        match: /(^|[\s(])curl\b|(^|[\s(])wget\b(?!\s+-O)/,
        head: 4,
        tail: 6,
        keep: /(\b\d{3}\b)|(^HTTP\/)|content-|set-cookie/i,
        budget: 30,
    },
];
/** Fallback for tools with no dedicated rule. */
const GENERIC_RULE = {
    name: "generic",
    match: /.*/,
    head: 10,
    tail: 20,
    keep: ALWAYS_KEEP,
    budget: 80,
};
function ruleFor(tool) {
    return RULES.find((r) => r.match.test(tool)) ?? GENERIC_RULE;
}

// --- engine/trim.js ---



const HEAD_NOTE = "␥ (tokenshave: removed %d of %d lines; head, tail and errors kept below)";
function gapMarker(removed, total) {
    void total;
    return `␥ (… +${removed} trimmed)`;
}
function looksLikeDiff(output) {
    let hits = 0;
    for (const line of output.split("\n").slice(0, 200)) {
        if (line.startsWith("diff --git ") || line.startsWith("@@ -"))
            hits++;
        if (hits >= 2)
            return true;
    }
    return false;
}
/**
 * The one public entry point.
 *
 * @param tool   The command that produced the output, e.g. "npm install express"
 *               or "vitest run". Used to pick a shaving rule.
 * @param output Raw tool output.
 */
function shave(tool, output) {
    const rawTokens = estimateTokens(output);
    const lines = output.split("\n");
    const rawLines = lines.length;
    if (looksLikeDiff(output)) {
        const { output: shaved, removed } = shaveDiff(output);
        const keptLines = rawLines - removed;
        return finalize(shaved, "diff", rawLines, keptLines, rawTokens);
    }
    const rule = ruleFor(tool);
    if (rawLines <= rule.budget) {
        return finalize(output, "none", rawLines, rawLines, rawTokens);
    }
    // First: collapse runs of consecutive identical lines (builders and CI
    // love to repeat the same warning 100x). Identical ≠ errors: repeated
    // warnings are pure noise.
    const deduped = dedupeRuns(lines);
    const { kept, removed, meaningful } = trimToBudget(rule, deduped.lines);
    const shaving = meaningful || deduped.removed > 0;
    const finalOutput = shaving ? kept.join("\n") : output;
    const finalKeptLines = shaving ? kept.length : rawLines;
    return finalize(finalOutput, shaving ? rule.name : "none", rawLines, finalKeptLines, rawTokens);
}
const RUN_MIN = 4;
/** Collapse runs of ≥ RUN_MIN consecutive identical lines to 2 + a marker. */
function dedupeRuns(lines) {
    const out = [];
    let removed = 0;
    let runCount = 0;
    for (let i = 0; i < lines.length;) {
        let j = i + 1;
        while (j < lines.length && lines[j] === lines[i])
            j++;
        const run = j - i;
        if (run >= RUN_MIN && lines[i].trim() !== "") {
            // keep the first two, note the collapse
            out.push(lines[i], lines[i + 1]);
            out.push(`␥ ... (tokenshave: ${run - 2} identical lines collapsed)`);
            removed += run - 2;
            runCount++;
            i = j;
            continue;
        }
        for (let k = i; k < j; k++)
            out.push(lines[k]);
        i = j;
    }
    return { lines: out, total: out.length, removed, runCount };
}
/**
 * Keep head + tail + keep-matches, then hard-cap the kept list at the rule
 * budget by dropping middle matches first. Pure function.
 */
function trimToBudget(rule, lines) {
    const total = lines.length;
    const keepSet = new Set();
    for (let i = 0; i < Math.min(rule.head, total); i++)
        keepSet.add(i);
    for (let i = Math.max(rule.head, total - rule.tail); i < total; i++)
        keepSet.add(i);
    if (rule.keep) {
        for (let i = 0; i < total; i++) {
            if (rule.keep.test(lines[i]))
                keepSet.add(i);
        }
    }
    let kept = [...keepSet].sort((a, b) => a - b);
    if (kept.length === total) {
        // nothing was filtered out at this stage; hand back the (deduped) lines
        // untouched — a possible dedupe collapse is handled by the caller
        return { kept: lines, removed: 0, meaningful: false };
    }
    // if the only lines we'd drop are blank, shaving buys nothing —
    // return the original untouched so the output stays byte-identical
    const dropped = [];
    let p = -1;
    for (const i of kept) {
        for (let j = p + 1; j < i; j++)
            dropped.push(j);
        p = i;
    }
    const meaningful = dropped.some((i) => lines[i].trim() !== "");
    const trimmedTotal = dropped.length;
    const keptLines = [HEAD_NOTE.replace("%d", String(trimmedTotal)).replace("%d", String(total))];
    let prev = -2;
    for (const i of kept) {
        if (prev >= 0 && i !== prev + 1) {
            keptLines.push(gapMarker(i - prev - 1, total));
        }
        keptLines.push(lines[i]);
        prev = i;
    }
    return { kept: keptLines, removed: trimmedTotal, meaningful };
}
function finalize(output, rule, rawLines, keptLines, rawTokens) {
    const keptTokens = estimateTokens(output);
    return { output, rule, rawLines, keptLines, rawTokens, keptTokens };
}


const TSH_MIN_CHARS = 50;

function tshHandle(input) {
  try {
    const e = JSON.parse(input);
    if (!e || e.hook_event_name !== "PostToolUse") return null
    if (e.tool_name !== "Bash") return null
    const response = e.tool_response;
    if (typeof response !== "string" || response.length < TSH_MIN_CHARS) return null
    const args = e.tool_input;
    const cmd =
      args && typeof args.command === "string" && args.command.trim() !== ""
        ? args.command
        : "bash";
    const result = shave(cmd, response);
    if (result.output === response) return null
    return JSON.stringify({
      continue: false,
      stopReason:
        "tokenshave: trimmed " +
        (result.rawLines - result.keptLines) +
        " of " +
        result.rawLines +
        " lines (head, tail and errors kept)",
      reason: result.output,
    });
  } catch {
    return null
  }
}

let tshChunks = [];
process.stdin.on("data", (chunk) => tshChunks.push(chunk));
process.stdin.on("end", () => {
  let output = null;
  try {
    output = tshHandle(Buffer.concat(tshChunks).toString("utf8"));
  } catch {
    output = null;
  }
  if (output) process.stdout.write(output);
  process.exit(0);
});
